def doc(name,title,text):(R/name).write_text('# '+title+'\n\n'+banner+text.rstrip()+'\n')
def table(headers,rows):return'| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+''.join('| '+' | '.join(str(x).replace('|','/')for x in row)+' |\n'for row in rows)+'\n'
def clock(s):return'non établie'if s is None else str(s//60)+' min'+(' '+str(s%60)+' s'if s%60 else'')
def number(n):return format(n,'.6g').replace('.',',')
def intensity(s):
 if s['sport']=='strength':return'Charge neuromusculaire : non déterminée ; aucune zone cardiaque utilisée comme dose de force.'
 if s['sport']=='swim':return'Zones écrites : '+', '.join(sorted({z for part in s['originalParts']for z in part.get('zones',[])}))+'. CSS crawl105s/100m disponible ; elle ne résout ni éducatifs, ni dos/brasse, ni allure individuelle de chaque bloc.'
 targets=s['intensity']['numericTargets'];text=' ; '.join(t['zone']+' / '+t['domain']+' : '+number(t['min'])+'–'+number(t['max'])+' '+t['unit']for t in targets)
 if s['sourceId']=='SEILER_BIKE_Z1_LONG':text+=' ; source55–72% FTP, plat strictement<72%, côtes courtes≤76%, FC<75%FCmax non calculable sans FCmax, cadence85–95rpm. Aucune équivalence FTP/LT1 mesurée affirmée.'
 if s['intensity']['reasons']:text+=' Conditions non résolues : '+', '.join({'explicit_FCmax_reference_missing':'FCmax absente','source_LT1_boundary_not_individually_verified':'limite LT1 personnelle non vérifiée'}.get(r,r)for r in s['intensity']['reasons'])+'.'
 return text+' Cibles numériques indicatives mises en forme pour la lecture ; valeurs brutes conservées. Domaines candidats issus de la doctrine TFCLab et du binding V22 conservés ; aucune validation individuelle.'
def decision(s):
 if s['sport']=='swim':return'Préciser les temps par nage et éducatif, les repos/transitions et vérifier le protocole entier dans le créneau ; aucune allure de test transférée à B'
 if s['sport']=='strength':return'Préciser compétence, tempos, côtés, charge et repos/transitions ; chronométrer la totalité avant de prescrire'
 if s['sourceId']=='C_BIKE_AERO_POSITION_DRILLS':return'Choisir la convention du dernier repos, vérifier les symptômes et la tolérance posturale, puis la récupération du microcycle'
 if s['phaseVariant']['requiresCoachPhasePolicy']:return'Accepter ou rejeter la politiqueB, puis documenter FCmax, contexte/ventilation, tolérance et récupération de cette dose'
 return'Vérifier la portée de la variante, les limites d’intensité, la tolérance et la récupération avant approbation individuelle'
def status(s):
 if s['errors']:return'non recevable dans son périmètre connu : '+', '.join(s['errors'])
 if s['phaseVariant']['proposedVariantCompatible']is None:return'variante à clarifier ; séance conditionnelle'
 if s['candidateTechnicallyExecutableIfPhasePolicyAuthorized']:return'contrat technique complet dans les paramètres natifs ; approbation individuelle absente'
 if s['phaseVariant']['requiresCoachPhasePolicy']:return'recette générique recevable uniquement sous politiqueB proposée ; autres conditions non résolues'
 return'proposition conditionnelle ; exécution ou prérequis non établis'
def why(s):
 if s['sourceId']=='SEILER_BIKE_Z1_LONG':return'Conserver une exposition aérobie autonome en base, en cohérence avec le levier natif de maintien d’intensité. La durée reste celle du calendrier/floor ; aucune formule TTE→minutes et aucune preuve de durabilité Ironman.'
 if s['sourceId']=='SEILER_RUN_Z1_EASY_LONG':return'Conserver90min Z1 strict et le placement S3 ; les Z2 du générique sont citées comme texte source, pas appliquées. La dérogation de floor ne valide ni intensité ni tolérance.'
 if s['sport']=='swim':return'Préserver trois présences natation et l’intention exacte de la source. Le chronométrage et les choix techniques doivent être documentés ; ni quota de mètres ajouté, ni CSS transférée aux autres nages.'
 if s['sourceId']=='C_BIKE_AERO_POSITION_DRILLS':return'Conserver6×10min de pratique posturale. Le créneau90min couvre les deux lectures85/90 sans choisir le dernier repos. Aucun gain postural ni tolérance aux10min déclarés acquis.'
 if s['sport']=='strength':return'Préserver le support de stabilité/mobilité prévu. Le créneau35min provient de la borne de fiche ; il ne prouve pas que toutes les exécutions y tiennent et ne remplace pas une force chargée prescrite.'
 return'Conserver l’exposition course et les capacités déclarées ; pas de progression acquise par passage du temps. Les séances faciles restent communes faute de justification d’une autre dose.'
